#!/usr/bin/env bash
# GENERATED by tools/gen-capture.mjs from capture-manifest.json. Do not edit; change the manifest and regenerate.
#
# Shoots every capture PNG of the intro video from the app's own debug control channel (the same method as scripts/screenshots.sh).
# Run it on a Mac that has a v0.13.0 (or newer) build, preferably a clean test user account. It refuses to start while another
# Nacho Combo is running (the Mac may be shared): it never kills a process it did not start unless you set KILL_RUNNING=1.
# It leaves the debug instance closed afterwards. Nothing is recorded from the screen; the app renders its own views.
#   APP=/path/to/NachoCombo.app scripts-dir/capture.sh <out dir>
# NOT YET RUN against a real build: ctl syntax comes from README.md and the source, see capture-manifest.json.
set -euo pipefail
APP="${APP:-build/NachoCombo.app}"
BIN="$APP/Contents/MacOS/NachoCombo"
OUT="${1:?usage: capture.sh <out dir>}"
mkdir -p "$OUT"; OUT="$(cd "$OUT" && pwd)"
if pgrep -x NachoCombo >/dev/null; then
  if [ "${KILL_RUNNING:-0}" = 1 ]; then pkill -x NachoCombo || true; sleep 1
  else echo "capture.sh: a NachoCombo process is already running; not touching it. Find out who uses it, or rerun with KILL_RUNNING=1 once it is yours to quit." >&2; exit 3; fi
fi
"$BIN" --debug-ctl >/dev/null 2>&1 &
sleep 4
ctl() { "$BIN" ctl "$@" >/dev/null; }
trap 'ctl quit || true' EXIT

# setup (every capture below runs on sample data)
ctl appearance dark
ctl gallery sample on

# c01-menu-bar.png: The six System Monitor menu bar items (CPU, memory, disk, network, sensors, battery) on sample numbers
ctl monitor menubar "$OUT/c01-menu-bar.png" sample

# c02-wall-home.png: The widget window with the gadget wall, no panel open
ctl gallery page home
sleep 1
ctl snapshot widget "$OUT/c02-wall-home.png"

# c03-wall-panel-calendar.png: The same window with the right-hand panel open on Calendar Clock, Settings tab (same window size as wall-home so the two overlay exactly)
ctl gallery page calendarClock
ctl gallery tab overview
sleep 1
ctl snapshot widget "$OUT/c03-wall-panel-calendar.png"

# c04-wall-panel-shortcuts.png: Window Snap panel, Shortcuts tab, same window size
ctl gallery page windowSnap
ctl gallery tab shortcuts
sleep 1
ctl snapshot widget "$OUT/c04-wall-panel-shortcuts.png"

# c05-wall-panel-permissions.png: Window Snap panel, Permissions tab, same window size
ctl gallery page windowSnap
ctl gallery tab permissions
sleep 1
ctl snapshot widget "$OUT/c05-wall-panel-permissions.png"

# c10-window-snap.png: Window Snap picture: a window snapped to the left half and one dragged to the right edge (the app draws the desktop around it)
ctl gallery preview windowSnap "$OUT/c10-window-snap.png"

# c11-system-monitor.png: System Monitor picture: menu bar items above the CPU panel, sample numbers
ctl gallery preview systemMonitor "$OUT/c11-system-monitor.png"

# c12-monitor-cpu-flyout.png: CPU panel with the CPU chart card hovered and its flyout beside it, sample numbers
ctl monitor flyout cpu 0 "$OUT/c12-monitor-cpu-flyout.png" sample

# c13-capture-float.png: Capture Float picture: dashed selection over a chart and the captured area floating with close, pin and share buttons
ctl gallery preview captureFloat "$OUT/c13-capture-float.png"

# c14-file-shelf.png: File Shelf picture: a file dragged onto the floating shelf holding a PDF, an image and a text snippet
ctl gallery preview fileShelf "$OUT/c14-file-shelf.png"

# c15-focus-dim.png: Focus Dim picture: one window bright in front, two dimmed behind (light variant reads better)
ctl gallery preview focusDim "$OUT/c15-focus-dim.png" light

# c16-disk-map.png: Disk Map window on the made-up sample disk, sunburst view colored by folder
ctl disk sample
ctl disk style sunburst
ctl disk color folder
sleep 1
ctl disk snapshot "$OUT/c16-disk-map.png"

# c20-combos.png: Combos page with the Desk combo selected (the whole page; the video crops the top)
ctl gallery page combos
ctl combo select desk
sleep 1
ctl gallery detail "$OUT/c20-combos.png"

# c21-quick-panel.png: Menu bar quick panel, tool list (Combo row first, status dots)
ctl panel list
sleep 1
ctl snapshot panel "$OUT/c21-quick-panel.png"

# c22-quick-panel-combos.png: Menu bar quick panel, combo screen
ctl panel combos
sleep 1
ctl snapshot panel "$OUT/c22-quick-panel-combos.png"

# teardown
ctl disk hide
ctl gallery page home
ctl gallery sample off
ctl appearance system

missing=0
for f in c01-menu-bar.png c02-wall-home.png c03-wall-panel-calendar.png c04-wall-panel-shortcuts.png c05-wall-panel-permissions.png c10-window-snap.png c11-system-monitor.png c12-monitor-cpu-flyout.png c13-capture-float.png c14-file-shelf.png c15-focus-dim.png c16-disk-map.png c20-combos.png c21-quick-panel.png c22-quick-panel-combos.png; do
  [ -s "$OUT/$f" ] || { echo "missing or empty: $f" >&2; missing=1; }
done
[ "$missing" = 0 ] && echo "all 15 captures written to $OUT" || exit 1
